suppressPackageStartupMessages({library(data.table);library(MVMR);library(MendelianRandomization);library(robustbase)})
args <- commandArgs(trailingOnly=TRUE)
file_arg <- grep('^--file=',commandArgs(trailingOnly=FALSE),value=TRUE)
script_dir <- if(length(file_arg)) dirname(normalizePath(sub('^--file=','',file_arg[1]))) else getwd()
root <- normalizePath(if(length(args)) args[1] else file.path(script_dir,'../..'),mustWork=TRUE)
src <- file.path(root,'original/results')
out <- file.path(root,'recomputed/reporting');dir.create(out,recursive=TRUE,showWarnings=FALSE)
set.seed(20261012)
d <- fread(file.path(src,'forward_mr/harmonized_sst2_cis_r2_0.001_Sepsis.tsv'))
d[,`:=`(F_recomputed=(beta_exposure/se_exposure)^2,Wald_beta=beta_outcome/beta_exposure,Wald_se=se_outcome/abs(beta_exposure))]
d[,`:=`(Wald_OR=exp(Wald_beta),Wald_CI_lower=exp(Wald_beta-1.96*Wald_se),Wald_CI_upper=exp(Wald_beta+1.96*Wald_se),Wald_P=2*pnorm(-abs(Wald_beta/Wald_se)))]
stopifnot(max(abs(d$F_recomputed-d$f_statistic))<1e-7)
fwrite(d,file.path(out,'cis_per_variant_complete.tsv'),sep='\t')
w <- d$beta_exposure^2/d$se_outcome^2
beta <- sum(d$beta_exposure*d$beta_outcome/d$se_outcome^2)/sum(w)
se <- sqrt(1/sum(w));Q<-sum((d$beta_outcome-beta*d$beta_exposure)^2/d$se_outcome^2)
fwrite(data.table(beta=beta,se=se,OR=exp(beta),CI_lower=exp(beta-1.96*se),CI_upper=exp(beta+1.96*se),P=2*pnorm(-abs(beta/se)),Q=Q,Q_df=1,Q_P=pchisq(Q,1,lower.tail=FALSE),MDE_harmful_OR=exp((qnorm(.975)+qnorm(.8))*se),MDE_protective_OR=exp(-(qnorm(.975)+qnorm(.8))*se)),file.path(out,'cis_recomputed.tsv'),sep='\t')
target<-c(1.02,1.0353,1.048923,1.08,1.082,1.10)
fwrite(data.table(target_OR=target,approximate_two_sided_power=pnorm(log(target)/se-qnorm(.975))+pnorm(-log(target)/se-qnorm(.975)),assumed_log_OR_SE=se),file.path(out,'cis_power_scenarios.tsv'),sep='\t')
mv <- fread(file.path(src,'multivariable_mr/harmonized_mvmr_instruments.tsv'))
screen <- fread(file.path(src,'instrument_validity/confounder_screened_mvmr_sensitivity.tsv'))
retained<-trimws(strsplit(screen$retained_rsids[1],';',fixed=TRUE)[[1]])
sets<-list(full_19=mv,screened_9=mv[rsid %chin% retained])
mvres<-list();rhores<-list();diagres<-list()
for(nm in names(sets)) {
  a<-sets[[nm]];X<-as.matrix(a[,.(beta_sst2,beta_hf)]);SX<-as.matrix(a[,.(se_sst2,se_hf)])
  inp<-format_mvmr(BXGs=X,BYG=a$beta_sepsis,seBXGs=SX,seBYG=a$se_sepsis,RSID=a$rsid)
  invisible(capture.output(Fc<-strength_mvmr(inp,gencov=0)))
  invisible(capture.output(Qv<-pleiotropy_mvmr(inp,gencov=0)))
  W<-1/a$se_sepsis^2;V<-solve(crossprod(X,W*X));b<-as.numeric(V%*%crossprod(X,W*a$beta_sepsis))
  q<-sum(W*(a$beta_sepsis-X%*%b)^2);df<-nrow(a)-2;phi<-max(1,q/df);s<-sqrt(diag(V)*phi)
  mvres[[nm]]<-data.table(instrument_set=nm,exposure=c('Circulating ST2 assay','Heart-failure liability'),nsnp=nrow(a),beta=b,se=s,OR=exp(b),CI_lower=exp(b-1.96*s),CI_upper=exp(b+1.96*s),P=2*pnorm(-abs(b/s)),conditional_F=as.numeric(Fc[1,]),validity_Q=Qv$Qstat,validity_Q_df=nrow(a)-3,validity_Q_P=Qv$Qpval,outcome_residual_Q=q,outcome_residual_Q_df=df,outcome_residual_Q_P=pchisq(q,df,lower.tail=FALSE),dispersion=phi)
  # Hypothetical sensitivity, NOT estimated phenotype correlation or an empirical overlap bound.
  rho<-sort(unique(round(c(-.99,seq(-.9,.9,.1),-.3,0,.3,.99),2)))
  rhores[[nm]]<-rbindlist(lapply(rho,function(r){
    covs<-phenocov_mvmr(matrix(c(1,r,r,1),2),SX)
    invisible(capture.output(ff<-strength_mvmr(inp,gencov=covs)))
    invisible(capture.output(qq<-pleiotropy_mvmr(inp,gencov=covs)))
    data.table(instrument_set=nm,hypothetical_error_rho=r,conditional_F_ST2=as.numeric(ff[1,1]),conditional_F_HF=as.numeric(ff[1,2]),validity_Q=qq$Qstat,validity_Q_df=nrow(a)-3,validity_Q_P=qq$Qpval)
  }))
}
fwrite(rbindlist(mvres),file.path(out,'mvmr_recomputed_full_and_screened.tsv'),sep='\t')
fwrite(rbindlist(rhores),file.path(out,'mvmr_expanded_hypothetical_covariance_grid.tsv'),sep='\t')
X<-as.matrix(mv[,.(beta_sst2,beta_hf)]);SX<-as.matrix(mv[,.(se_sst2,se_hf)])
obj<-mr_mvinput(bx=X,bxse=SX,by=mv$beta_sepsis,byse=mv$se_sepsis,exposure=c('ST2 assay','HF'),snps=mv$rsid)
set.seed(20261012);rob<-mr_mvivw(obj,model='random',robust=TRUE)
set.seed(20261012);rr<-lmrob(mv$beta_sepsis~X-1,weights=1/mv$se_sepsis^2,k.max=500,maxit.scale=500)
ss<-summary(rr);bb<-ss$coef[,1];ss_adj<-ss$coef[,2]/min(ss$sigma,1)
stopifnot(max(abs(bb-rob@Estimate))<1e-7,max(abs(ss_adj-rob@StdError))<1e-7)
fwrite(data.table(exposure=c('Circulating ST2 assay','Heart-failure liability'),beta=rob@Estimate,se=rob@StdError,OR=exp(rob@Estimate),CI_lower=exp(rob@CILower),CI_upper=exp(rob@CIUpper),P=rob@Pvalue,robust_scale=ss$sigma,converged=rr$converged,robust_scale_Q=rob@Heter.Stat[1],robust_scale_Q_P=rob@Heter.Stat[2]),file.path(out,'robust_mvmr_exact_implementation.tsv'),sep='\t')
fwrite(data.table(rsid=mv$rsid,robust_weight=rr$rweights,regression_residual=rr$residuals),file.path(out,'robust_mvmr_variant_weights.tsv'),sep='\t')
saveRDS(list(package=rob,direct_lmrob=rr),file.path(out,'robust_mvmr_fit.rds'))
writeLines(capture.output(sessionInfo()),file.path(out,'session_info.txt'))
writeLines(c('Robust MVMR: MendelianRandomization::mr_mvivw(model="random", robust=TRUE).','Implementation cross-checked against robustbase::lmrob, no intercept; weights seY^-2; k.max=500,maxit.scale=500; random-effects SE = summary(lmrob)$coef[,2]/min(summary(lmrob)$sigma,1).','Modified validity Q includes exposure-association uncertainty; outcome residual Q and robust-scale Q are different diagnostics and must not be compared as the same statistic.','Expanded rho grid is hypothetical error-correlation stress testing, not inferred cohort overlap; point estimates and conventional weighted-regression SE are not overlap-corrected.','Power assumes asymptotic normality, valid instruments and fixed observed standard error, and does not incorporate LD/assay/exclusion-restriction uncertainty.'),file.path(out,'methods_notes.txt'))
print(rbindlist(mvres));print(fread(file.path(out,'robust_mvmr_exact_implementation.tsv')))
